#include<bits/stdc++.h>
using namespace std;
#define ll long long
const int N = 1010;
vector<int> g[N];
int a[N];
int n,k;
int ans;
void dfs(int x,int fa,int tot,int le){
    tot+=a[x];
    if(tot>k){
        ans = max(ans,le);
        return;
    }
    le++;
    ans = max(ans,le);
    for(int i:g[x]){
        if(i!=fa){
            dfs(i,x,tot,le);
