#include <cstdio>

using namespace std;

const int N = 2e5 + 5;
const int mod = 1e9 + 7;

int n, m;
int pre[N], suf[N];
int vis[N];
int cnt;
int ans;

int main() {
    scanf("%d%d", &n, &m);
    ans = 1;
    for (int i = 1; i <= m; i++) {
        int a, b;
        scanf("%d%d", &a, &b);
        if (pre[b] == a && suf[a] == b)
            continue;
        if (pre[b] || suf[a])
            ans = 0;
        pre[b] = a;
        suf[a] = b;
    }
    for (int i = 1; i <= n; i++) {
        if (vis[i])
            continue;
        int j = i;
        while (j) {
            if (vis[j] == i)
                ans = 0;
            if (vis[j])
                break;
            vis[j] = i;
            j = suf[j];
        }
    }
    for (int i = 1; i <= n; i++)
        cnt += !pre[i];
    for (int i = 1; i <= cnt; i++)
        ans = 1ll * ans * i % mod;
    printf("%d\n", ans);
    return 0;
}
